/**
 * REAL ENCODER OUTPUT, one 1×1 and one 2×3 per family the image proxy serves, and a TIFF it does not.
 * Generated once and pinned: PIL 10.2.0 (`Image.new(mode, (w, h), colour).save(buffer, format, …)`;
 * JPEG baseline, `progressive=True` and `exif=`; WebP `lossless=False`, `lossless=True` and RGBA for
 * VP8X; APNG `save_all=True`; ICO `sizes=`) and sharp 0.35.4 for AVIF (`sharp({ create }).avif()`). A
 * hand-typed header would only test the reader against its author; these are what encoders write.
 */
const b64 = (s: string): Uint8Array => Uint8Array.from(Buffer.from(s, "base64"));

